-- Passage rg10-theme-summary-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('867c859c-b4a3-5d8e-928b-72a4870b9830', 'rg10-theme-summary-p02', (select id from public.skills where slug = 'read-g10-theme-summary'), null,
        '9-12', $q$Third Leg$q$, $q$I never cross the finish line.
That job belongs to Marisol,
who runs the last hundred meters
while the bleachers rise like a wave.

My part is the curve.
I take the baton from Dev,
still warm from his hand,
and I carry it through the bend
where no camera ever points.

For eleven seconds, the race is mine,
and no one is watching it.
I lean into the turn.
I count my steps the way Coach taught us,
and I stretch my arm into the open lane.

Then I let go.
That is the hardest part,
harder than the running.
The baton leaves my fingers
before I know if it will land.

Marisol takes it clean.
I hear the crowd before I see her.
By the time I lift my head,
she is already a blur of blue,
already the one they will remember.

Later, in the photo on the school website,
I am a shape behind her shoulder,
bent over, hands on my knees,
my face turned toward the track.
I keep the photo anyway.
You can see the baton in her hand.
You can see that it got there.$q$, 'draft')
