  ('2c6ecee8-f649-5879-bdbd-8af2d59b0683', null, (select id from public.skills where slug = 'read-g10-theme-summary'), null, 'easy',
   $q$Which statement best expresses the theme of the fable?$q$, $q$[{"text":"Kites fly best on windy afternoons above open hillside meadows.","is_correct":false,"misconception_token":"topic-not-theme"},{"text":"The ties that seem to hold us back can be what allow us to rise.","is_correct":true},{"text":"Birds are wiser than kites and should be trusted in every matter.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Anyone who wishes for freedom will always end up stuck in a tree.","is_correct":false,"misconception_token":"overstates-claim"}]$q$::jsonb, $q$The ties that seem to hold us back can be what allow us to rise.$q$, $q$Once cut loose, the kite falls, and later it learns the string's pull keeps it facing the wind. The windy meadow choice describes the setting, not the lesson.$q$, 'draft', '22ab2113-ca53-5255-9921-de940cc475f3')
