  ('fbda63df-c28e-5490-b2ae-81e0af833e8c', null, (select id from public.skills where slug = 'read-g10-theme-summary'), null, 'easy',
   $q$Which choice is the best objective summary of the fable?$q$, $q$[{"text":"A foolish, ungrateful kite gets exactly the punishment it deserves for complaining all afternoon long.","is_correct":false,"misconception_token":"includes-opinion"},{"text":"A kite takes off on a windy afternoon and tells a sparrow how much it admires the drifting clouds.","is_correct":false,"misconception_token":"too-narrow"},{"text":"A kite breaks its string, drifts beside the clouds for days, and finally returns home on its own.","is_correct":false,"misconception_token":"adds-false-detail"},{"text":"A kite resents its string and breaks free, falls into a tree, and after the girl repairs it, learns the string helps it fly.","is_correct":true}]$q$::jsonb, $q$A kite resents its string and breaks free, falls into a tree, and after the girl repairs it, learns the string helps it fly.$q$, $q$The correct summary includes the complaint, the fall, the repair, and the new understanding without judgment. Calling the kite foolish and deserving punishment adds the reader's opinion.$q$, 'draft', '22ab2113-ca53-5255-9921-de940cc475f3')
