  ('26f8cc1f-dc75-5133-bcbe-e63c64ba0124', null, (select id from public.skills where slug = 'read-g10-theme-summary'), null, 'easy',
   $q$Which statement best expresses the theme of the poem?$q$, $q$[{"text":"Creeks that are paved over always dry up and disappear within a few years.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"A place's past stays present beneath its changes, waiting for someone to notice it.","is_correct":true},{"text":"Old maps are fragile and must be stored under glass in a library basement.","is_correct":false,"misconception_token":"topic-not-theme"},{"text":"Towns were much better places to live before roads and stores were built.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$A place's past stays present beneath its changes, waiting for someone to notice it.$q$, $q$The buried creek "still runs," and the speaker learns to hear the town's past under its present. The poem never judges the old town as better; it focuses on noticing what remains.$q$, 'draft', 'f34a3c20-71b8-55e0-971c-23ba0630eb73')
