  ('9ff8bc4d-d504-5572-976c-271b524ad221', null, (select id from public.skills where slug = 'read-g10-theme-summary'), null, 'medium',
   $q$How does the archivist's statement that the creek "still runs" develop the theme?$q$, $q$[{"text":"It warns that the creek is likely to flood the bank and the bus stop.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It shows that something from the past continues beneath the modern town.","is_correct":true},{"text":"It shows that the town plans to uncover the creek in the near future.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It proves that the map from 1890 is full of errors and cannot be trusted.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$It shows that something from the past continues beneath the modern town.$q$, $q$The creek was covered, not removed, and it flows "under the bank, / under the bus stop," a concrete image of the past continuing below the present. No flooding or plan to uncover it is mentioned.$q$, 'draft', 'f34a3c20-71b8-55e0-971c-23ba0630eb73')
